target.css:
:root {
  --ink: #26312f;
  --muted: #68736d;
  --surface: #fffdf7;
  --line: #d8d3c6;
  --sand: #f2ead8;
  --clay: #bd6046;
  --clay-dark: #914431;
  --mint: #dcebe0;
}

* {
  box-sizing: border-box;
}

.prep-ticket {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.ticket-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px 14px;
  background: var(--sand);
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.15;
}

.status {
  flex: 0 0 auto;
  padding: 5px 8px;
  color: var(--clay-dark);
  background: var(--surface);
  border: 1px solid var(--clay);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.specimen-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 18px;
  border-bottom: 1px solid var(--line);
}

.specimen-mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  background: var(--mint);
  border-radius: 10px;
  font-size: 19px;
}

.specimen-row strong {
  display: block;
  font-size: 14px;
  line-height: 1.2;
}

.specimen-row p {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  padding: 12px 18px;
  border-bottom: 1px solid var(--line);
}

.details div {
  padding-left: 12px;
  border-left: 1px solid var(--line);
}

.details div:first-child {
  padding-left: 0;
  border-left: 0;
}

.details dt {
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.details dd {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
}

.work-list {
  display: flex;
  gap: 8px;
  padding: 11px 18px;
}

.work-list p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.check,
.pending {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
}

.check {
  color: var(--ink);
  background: var(--mint);
}

.pending {
  color: var(--surface);
  background: var(--clay);
}

.ticket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  background: var(--sand);
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}

button {
  padding: 7px 10px;
  color: var(--surface);
  background: var(--clay);
  border: 1px solid var(--clay);
  border-radius: 7px;
  font-size: 12px;
  font-weight: 700;
}

